input.command:
python3 -c "
import sys,json,re
content = open('/root/.local/share/opencode/tool-output/tool_f5c39eee6001Pl1xybrsODoKCt').read()
scripts = re.findall(r'<script type=\"application/json\"[^>]*>(.*?)</script>', content, re.DOTALL)
for s in scripts:
    try:
        d = json.loads(s)
        if isinstance(d, dict) and 'payload' in d:
            p = d['payload']
            if isinstance(p, dict) and 'preloadedQueries' in p:
                for q in p['preloadedQueries']:
                    if q.get('queryName') == 'IssueIndexPageQuery':
                        result = q.get('result', {})
                        data = result.get('data', {})
                        repo = data.get('repository', {})
                        issues = repo.get('issues', {})
                        nodes = issues.get('nodes', [])
                        count = 0
                        for node in nodes:
                            if isinstance(node, dict) and 'pull_request' not in str(node).lower() and '__typename' in node and node.get('__typename') == 'Issue':
                                count += 1
                        print('ISSUE_COUNT', count)
                        print('NODES', len(nodes))
                        break
    except Exception as e:
        pass
"

